import { Component, inject } from '@angular/core';
import { ConsolidadoBasicoService } from '../../main/reportes/services/consolidado-basico.service';
import { Credito } from '../../models/credito.model';
import { CreditoService } from '../../controllers/credito.service';
import { ProgressBarConsolidadoComponent } from "../../main/informes/shared/progress-bar-consolidado/progress-bar-consolidado.component";

@Component({
  selector: 'app-actualizar-estados-cuenta',
  imports: [ProgressBarConsolidadoComponent],
  templateUrl: './actualizar-estados-cuenta.component.html',
  styleUrl: './actualizar-estados-cuenta.component.css'
})
export class ActualizarEstadosCuentaComponent {
  progress:number=0
  creditos:Credito[]=[]

  progressActualizacion =0 

  private creditoController = inject(CreditoService)
  private consolidadoBasico = inject(ConsolidadoBasicoService)

  async ngOnInit(){
    this.consolidadoBasico.progress$.subscribe( p => {
      this.progress=p
    })
    this.creditos= await this.consolidadoBasico.fetchData()
  }

  public actualizarEstadosDeCuenta(){
    this.creditoController.actualizarEstadosCuentaMasivaLocal(this.creditos)
  }
}
