import { inject, Injectable } from '@angular/core';
import { Credito } from '../../../models/credito.model';
import { FilterOptions, SuperConsolidadoService } from '../../informes/services/consolidado.super.service';


@Injectable({
    providedIn: 'root'
})
export class ConsolidadoBasicoService extends SuperConsolidadoService {
    protected endpoint = 'api/consolidado/historico'

    constructor() {
        super()
        this.initData()
    }

    override filter = (c: Credito, options?: FilterOptions) => {
        if (!c.creditos_pagos?.length) {
            return false
        }

        if (!c.liberado_fecha) {
            return false;
        }

        return true;
    };

    override map = (c:Credito) => {
        return {}
    }
}
