import { Routes } from "@angular/router";
import { comercialesRoutes } from "./productos-comerciales/productos.comerciales.routes";
import { financierosRoutes } from "./productos-financieros/productos.financieros.routes";
import { documentosRoutes } from "./documentos/documentos.routes";
import { MigrarExcelesComponent } from "./migrar-exceles/migrar-exceles.component";
import { UtileriaComponent } from "./utileria/utileria.component";
import { MigrarGestionesComponent } from "./migrar-gestiones/migrar-gestiones.component";
import { ActualizarEstadosCuentaComponent } from "./actualizar-estados-cuenta/actualizar-estados-cuenta.component";
import { ConfiguracionHistoricoComponent } from "./configuracion-historico/configuracion-historico.component";

export const configRoutes:Routes=[
    { path:'productos/comerciales', children:comercialesRoutes },
    { path:'productos/financieros', children:financierosRoutes },
    { path:'documentos', children:documentosRoutes },
    { path:'apoyos', loadChildren: () => import('./programa-apoyos/apoyos.routes').then(m=>m.apoyosRoutes)},
    { path:'migracion', component: MigrarExcelesComponent },
    { path:'migracion/gestiones', component: MigrarGestionesComponent },
    { path:'modalidades', loadChildren: ()=> import('./modalidades/modalidades.routes').then(m => m.modalidadesRoutes)} ,
    { path:'utileria', component:UtileriaComponent },
    { path:'actualizar-estados-cuenta', component:ActualizarEstadosCuentaComponent },
    { path:'historico', component:ConfiguracionHistoricoComponent },
]