@Component({
    selector: 'app-form-productos-financieros',
    imports: [
        GenericFormComponent,
    ],
    templateUrl: './form-productos-financieros.component.html',
    styleUrl: './form-productos-financieros.component.css'
})
export class FormProductosFinancierosComponent {
  form:Form=FORM_DATA
  edit?:ProductoFinanciero

  constructor(
    public controller: ProductoFinancieroService, private route: ActivatedRoute,
    private router:Router,
  ){}

  ngOnInit(){
    this.checkIdParam()
  }

  copyOf(value:any){
    return JSON.parse(JSON.stringify(value))
  }

  checkIdParam(){
    this.route.paramMap.subscribe(async (params)=>{
      if(params.get('id') && !isNaN(parseInt(params.get('id')??''))){
        const id= parseInt(params.get('id')!)
        if(this.edit && this.edit.id== id){
          return
        }
        
        this.edit= await this.controller.find(id, ["plazos","documentos.documento",])
        console.log(this.edit)
      }
    })
  }

  updateUrl(){
    if(!this.edit?.id) return
    this.router.navigate(['/configuracion/productos/financieros/editar', this.edit?.id]);
  }
}
