import { Component, EventEmitter, Input, Output, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { TitleCasePipe } from '@angular/common';
import { TablaConfigurada, VisualizationMode } from '../../../../main/informes/informe-tabla-configurada/interfaces/tabla.configurada';

@Component({
  selector: 'app-configuracion-card',
  imports: [FormsModule, TitleCasePipe],
  templateUrl: './configuracion-card.component.html',
  styleUrl: './configuracion-card.component.css'
})
export class ConfiguracionCardComponent {
  @Input() config: TablaConfigurada | null = null;
  @Input() seccion: string = '';

  @Output() editRequest = new EventEmitter<TablaConfigurada>();
  @Output() cloneRequest = new EventEmitter<TablaConfigurada>();
  @Output() deleteRequest = new EventEmitter<TablaConfigurada>();
  @Output() saveConfig = new EventEmitter<TablaConfigurada>();

  // Estados independientes para esta tarjeta
  showFilterDetails = signal(false);
  showViewSelector = signal(false);
  showConfigOptions = false;

  // Estados para la funcionalidad de copiar JSON
  copiandoJSON = false;
  mostrarNotificacion = false;
  mensajeNotificacion = '';

  constructor() { }

  /**
   * Obtiene las configuraciones de tablas para esta sección
   */
  get tablasDeSeccion(): TablaConfigurada[] {
    return this.config ? [this.config] : [];
  }

  /**
   * Obtiene un texto descriptivo para la configuración
   */
  getDescripcionConfiguracion(config: TablaConfigurada): string {
    const numVistas = config.configuracion.finalViews?.length || 0;
    const numFiltros = Object.keys(config.configuracion.filtros || {}).length;

    return `${numVistas} vista(s) final(es), ${numFiltros} filtro(s)`;
  }

  /**
   * Obtiene el estado de la configuración
   */
  getEstadoConfiguracion(config: TablaConfigurada): string {
    const numVistas = config.configuracion.finalViews?.length || 0;
    return numVistas > 0 ? 'Completa' : 'Incompleta';
  }

  /**
   * Obtiene la clase CSS para el badge de estado
   */
  getEstadoClass(config: TablaConfigurada): string {
    const numVistas = config.configuracion.finalViews?.length || 0;
    const style = numVistas > 0 ? 'bg-success' : 'bg-warning';

    return "badge badge-sm " + style;
  }

  /**
   * Actualiza rápidamente la vista por defecto sin entrar en modo edición
   */
  async actualizarVistaPorDefecto(config: TablaConfigurada, viewId: string): Promise<void> {
    const configActualizada: TablaConfigurada = JSON.parse(JSON.stringify(config));
    configActualizada.configuracion.defaultViewId = viewId;

    this.saveConfig.emit(configActualizada);
  }

  /**
   * Actualiza rápidamente el modo de visualización sin entrar en modo edición
   */
  async actualizarModoVisualizacion(config: TablaConfigurada, mode: VisualizationMode): Promise<void> {
    try {
      // Crear copia actualizada de la configuración
      const configActualizada: TablaConfigurada = JSON.parse(JSON.stringify(config));
      configActualizada.configuracion.visualizationMode = mode;

      // Emitir evento para guardar en backend
      this.saveConfig.emit(configActualizada);
    } catch (error) {
      console.error('Error al actualizar modo de visualización:', error);
      alert('Error al actualizar el modo de visualización. Por favor, inténtelo de nuevo.');
    }
  }

  /**
   * Obtiene el modo de visualización actual de una configuración
   */
  getModoVisualizacion(config: TablaConfigurada): VisualizationMode {
    return config.configuracion.visualizationMode || 'tables';
  }

  /**
   * Obtiene las opciones de modo de visualización disponibles
   */
  getOpcionesModoVisualizacion(): Array<{ value: VisualizationMode, label: string, icon: string }> {
    return [
      { value: 'tables', label: 'Tablas', icon: 'bi-table' },
      { value: 'graphs', label: 'Gráficas', icon: 'bi-graph-up' }
    ];
  }

  /**
   * Verifica si una vista final está seleccionada como por defecto
   */
  esVistaSeleccionada(config: TablaConfigurada, viewName: string): boolean {
    const viewId = this.generarViewId(viewName);
    return viewId === config.configuracion.defaultViewId;
  }

  /**
   * Genera un ID único para una vista final basado en su nombre
   */
  generarViewId(viewName: string | null): string {
    return viewName?.toLowerCase()
      .replace(/[^a-z0-9]/g, '_')
      .replace(/_+/g, '_')
      .replace(/^_|_$/g, '') || 'vista_' + Date.now();
  }

  /**
   * Obtiene los filtros formateados para visualización
   * Parsea filtros complejos y los retorna en formato estructurado
   */
  getFiltrosFormateados(config: TablaConfigurada): Array<{ columna: string, filtros: string[], esMultiple: boolean }> {
    const filtros = config.configuracion.filtros || {};
    const resultado: Array<{ columna: string, filtros: string[], esMultiple: boolean }> = [];

    Object.entries(filtros).forEach(([columna, valorFiltro]) => {
      if (valorFiltro && typeof valorFiltro === 'string' && valorFiltro.trim()) {
        const filtrosParseados = this.parseFilterValue(valorFiltro);
        resultado.push({
          columna,
          filtros: filtrosParseados,
          esMultiple: filtrosParseados.length > 1
        });
      }
    });

    return resultado;
  }

  /**
   * Parsea un valor de filtro que puede contener múltiples condiciones
   * Soporta operadores | (OR) y & (AND)
   */
  parseFilterValue(filterValue: string): string[] {
    if (!filterValue || !filterValue.trim()) {
      return [];
    }

    const trimmed = filterValue.trim();

    // Si no hay operadores lógicos, retornar como condición simple
    if (!trimmed.includes('|') && !trimmed.includes('&')) {
      return [trimmed];
    }

    // Separar por | (OR) - división principal
    const orGroups = trimmed.split('|').map(group => group.trim()).filter(group => group);

    // Para cada grupo OR, separar por & (AND) si existe
    const condiciones: string[] = [];
    orGroups.forEach(orGroup => {
      if (orGroup.includes('&')) {
        const andConditions = orGroup.split('&').map(cond => cond.trim()).filter(cond => cond);
        condiciones.push(...andConditions);
      } else {
        condiciones.push(orGroup);
      }
    });

    return condiciones;
  }

  // Funciones de utilidad para la UI
  abreviarNombreVista(nombre: string|null): string {
    if(!nombre) return 'S/N';
    // Abrevia nombres largos de vistas manteniendo la legibilidad
    if (nombre.length <= 12) return nombre;

    const palabras = nombre.split(' ');
    if (palabras.length > 1) {
      // Para nombres con múltiples palabras, usar iniciales
      return palabras.map(p => p.charAt(0)).join('').toUpperCase();
    } else {
      // Para nombres largos de una palabra, truncar
      return nombre.substring(0, 10) + '...';
    }
  }

  abreviarTexto(texto: string|null, longitudMaxima: number = 15): string {
    if(!texto) return '';
    if (texto.length <= longitudMaxima) return texto;
    return texto.substring(0, longitudMaxima - 3) + '...';
  }

  getUltimaActualizacion(config: TablaConfigurada): string {
    if(!config.updated_at) return 'Fecha no disponible'

    const ahora = new Date();
    const fechaActualizacion = new Date(config.updated_at);

    // Verificación básica por si updated_at no es válido
    if (isNaN(fechaActualizacion.getTime())) {
      return 'Fecha no disponible';
    }

    // Normalizamos ambas fechas a medianoche para comparar solo días
    const hoy = new Date(ahora.getFullYear(), ahora.getMonth(), ahora.getDate());
    const fecha = new Date(fechaActualizacion.getFullYear(), fechaActualizacion.getMonth(), fechaActualizacion.getDate());

    const diferenciaMs = hoy.getTime() - fecha.getTime();
    const diferenciaDias = Math.floor(diferenciaMs / (1000 * 60 * 60 * 24));

    if (diferenciaDias === 0) {
      return 'Hoy';
    } else if (diferenciaDias === 1) {
      return 'Ayer';
    } else if (diferenciaDias > 1 && diferenciaDias <= 7) {
      return `Hace ${diferenciaDias} días`;
    } else {
      // Opcional: formatear como fecha legible (ej. "10/04/2025")
      return fechaActualizacion.toLocaleDateString();
    }
  }

  // Manejadores de eventos
  onEditConfig(): void {
    if (this.config) {
      this.editRequest.emit(this.config);
    }
  }

  onCloneConfig(): void {
    if (this.config) {
      this.cloneRequest.emit(this.config);
    }
  }

  onDeleteConfig(): void {
    if (this.config) {
      this.deleteRequest.emit(this.config);
    }
  }

  toggleFilterDetails(): void {
    this.showFilterDetails.set(!this.showFilterDetails());
  }

  toggleViewSelector(): void {
    this.showViewSelector.set(!this.showViewSelector());
  }

  /**
   * Obtiene la vista final actual seleccionada como por defecto
   */
  getVistaActualPorDefecto(): any {
    if (!this.config?.configuracion.defaultViewId || !this.config.configuracion.finalViews) {
      return null;
    }

    return this.config.configuracion.finalViews.find(
      (view: any) => this.generarViewId(view.name) === this.config!.configuracion.defaultViewId
    );
  }

  // Métodos para la funcionalidad de Copiar JSON

  /**
   * Genera el JSON formateado de la configuración actual
   * @returns JSON string formateado con indentación
   */
  generarJSONConfiguracion(): string {
    if (!this.config) {
      throw new Error('No hay configuración disponible para generar JSON');
    }

    try {
      // Crear una copia limpia de la configuración
      const configLimpia:TablaConfigurada =  {
        ...JSON.parse(JSON.stringify(this.config)),
        id:0,
      }


      // Generar JSON formateado
      return JSON.stringify(configLimpia, null, 2);
    } catch (error) {
      console.error('Error al generar JSON:', error);
      throw new Error('No se pudo generar el JSON de la configuración');
    }
  }

  /**
   * Copia el JSON de la configuración al portapapeles
   * Maneja tanto el Clipboard API moderno como fallbacks
   */
  async copiarJSONAlPortapapeles(): Promise<void> {
    if (!this.config || this.copiandoJSON) {
      return;
    }

    this.copiandoJSON = true;

    try {
      // Generar el JSON
      const jsonString = this.generarJSONConfiguracion();

      // Intentar usar el Clipboard API moderno
      if (navigator.clipboard && window.isSecureContext) {
        await navigator.clipboard.writeText(jsonString);
        this.mostrarNotificacionExito('JSON copiado al portapapeles');
      } else {
        // Fallback para navegadores antiguos o contextos no seguros
        this.copiarConFallback(jsonString);
        this.mostrarNotificacionExito('JSON copiado al portapapeles');
      }

      // Cerrar el menú de opciones después de copiar
      this.showConfigOptions = false;

    } catch (error) {
      console.error('Error al copiar JSON:', error);
      this.mostrarNotificacionError('No se pudo copiar el JSON. Intente nuevamente.');
    } finally {
      this.copiandoJSON = false;
    }
  }

  /**
   * Método de fallback para copiar al portapapeles usando textarea oculto
   * @param text Texto a copiar
   */
  private copiarConFallback(text: string): void {
    const textarea = document.createElement('textarea');
    textarea.value = text;
    textarea.style.position = 'fixed';
    textarea.style.left = '-999999px';
    textarea.style.top = '-999999px';
    document.body.appendChild(textarea);

    textarea.focus();
    textarea.select();

    try {
      document.execCommand('copy');
    } catch (error) {
      console.error('Error en fallback de copia:', error);
      throw new Error('No se pudo copiar el texto');
    } finally {
      document.body.removeChild(textarea);
    }
  }

  /**
   * Muestra notificación de éxito
   * @param mensaje Mensaje a mostrar
   */
  private mostrarNotificacionExito(mensaje: string): void {
    this.mensajeNotificacion = mensaje;
    this.mostrarNotificacion = true;

    // Ocultar notificación después de 3 segundos
    setTimeout(() => {
      this.mostrarNotificacion = false;
    }, 3000);
  }

  /**
   * Muestra notificación de error
   * @param mensaje Mensaje a mostrar
   */
  private mostrarNotificacionError(mensaje: string): void {
    this.mensajeNotificacion = mensaje;
    this.mostrarNotificacion = true;

    // Ocultar notificación después de 5 segundos (más tiempo para leer errores)
    setTimeout(() => {
      this.mostrarNotificacion = false;
    }, 5000);
  }
}