import { Component, EventEmitter, Input, Output, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { TablaConfigurada, VisualizationMode } from '../../../../main/informes/informe-tabla-configurada/interfaces/tabla.configurada';
import { InformeTablaDinamicaLocalComponent } from '../../../../main/informes/informe-tabla-dinamica-local/informe-tabla-dinamica-local.component';
import { VanillaDialogService } from '../../../../services/vanilla-dialog/vanilla-dialog.service';
import { ConfiguracionCardComponent } from '../configuracion-card/configuracion-card.component';
import { parseAndValidateTablaConfigurada, normalizarTablaConfigurada, generarJSONEjemplo } from '../../../../utils/tabla-configurada.utils';

@Component({
  selector: 'app-configuracion-tablas-seccion',
  imports: [
    FormsModule,
    InformeTablaDinamicaLocalComponent,
    ConfiguracionCardComponent
  ],
  templateUrl: './configuracion-tablas-seccion.component.html',
  styleUrl: './configuracion-tablas-seccion.component.css'
})
export class ConfiguracionTablasSeccionComponent {
  @Input() seccion: string = '';
  @Input() tablasConfiguradas: TablaConfigurada[] = [];
  @Input() rawData: any[] = [];

  @Output() saveTablaConfiguracion = new EventEmitter<TablaConfigurada>();
  @Output() addTablaConfiguracion = new EventEmitter<string>();
  @Output() deleteTablaConfiguracion = new EventEmitter<TablaConfigurada>();

  constructor(private dialogService: VanillaDialogService) { }

  // Estado para manejar la edición
  configuracionEditando = signal<TablaConfigurada | null>(null);
  modoEdicion = signal(false);

  // Configuración temporal mientras se edita
  configuracionTemporal: TablaConfigurada | null = null;

  // Estado para manejar la importación desde JSON
  mostrarImportacion = signal(false);
  jsonImportacion = signal('');
  erroresImportacion = signal<string[]>([]);
  procesandoImportacion = signal(false);

  // Getter y setter para el nombre de la configuración que se está editando
  get nombreConfiguracion(): string {
    return this.configuracionEditando()?.nombre || '';
  }

  set nombreConfiguracion(value: string) {
    const configActual = this.configuracionEditando();
    if (configActual) {
      configActual.nombre = value;
    }
  }

  /**
   * Obtiene las configuraciones de tablas para esta sección
   */
  get tablasDeSeccion(): TablaConfigurada[] {
    return this.tablasConfiguradas.filter(config => config.seccion === this.seccion);
  }

  /**
   * Inicia la edición de una configuración
   */
  editarConfiguracion(config: TablaConfigurada): void {
    // Crear una copia profunda para evitar modificar el original hasta guardar
    this.configuracionTemporal = JSON.parse(JSON.stringify(config));
    this.configuracionEditando.set(this.configuracionTemporal);
    this.modoEdicion.set(true);
  }

  /**
   * Crea una nueva configuración para esta sección
   */
  crearNuevaConfiguracion(): void {
    const nuevaConfig: TablaConfigurada = {
      seccion: this.seccion,
      configuracion: {
        finalViews: [],
        crossTabConfigs: [],
        filterBasedConfigs: [],
        filtros: {},
        defaultViewId: undefined,
      },
      nombre: '',
      id: 0,
      created_at: ''
    };

    this.configuracionTemporal = nuevaConfig;
    this.configuracionEditando.set(this.configuracionTemporal);
    this.modoEdicion.set(true);
  }

  /**
   * Guarda la configuración actual
   */
  guardarConfiguracion(): void {
    const configActual = this.configuracionEditando();
    if (!configActual) return;

    // Validar que tenga nombre
    if (!configActual.nombre || configActual.nombre.trim() === '') {
      alert('Debe especificar un nombre para la configuración antes de guardar.');
      return;
    }

    // Validar que tenga al menos una vista final
    if (!configActual.configuracion.finalViews || configActual.configuracion.finalViews.length === 0) {
      alert('Debe configurar al menos una vista final antes de guardar.');
      return;
    }

    this.saveTablaConfiguracion.emit(configActual);
    this.cancelarEdicion();
  }

  /**
   * Cancela la edición actual
   */
  cancelarEdicion(): void {
    this.configuracionEditando.set(null);
    this.modoEdicion.set(false);
    this.configuracionTemporal = null;
  }

  /**
   * Elimina una configuración con confirmación
   */
  async eliminarConfiguracion(config: TablaConfigurada): Promise<void> {
    const dialogRef = this.dialogService.show({
      title: 'Confirmar Eliminación',
      body: `¿Está seguro de eliminar la configuración "${config.nombre || 'Sin nombre'}"? Esta acción se puede deshacer.`,
      tipo: 'confirm',
      respYes: 'Eliminar',
      respNo: 'Cancelar',
      size: 'm'
    });

    dialogRef.subscribe(response => {
      if (response?.closedByAgree) {
        this.deleteTablaConfiguracion.emit(config);
      }
    });
  }

  
  /**
   * Establece la vista final por defecto
   */
  setVistaPorDefecto(viewId: string): void {
    const configActual = this.configuracionEditando();
    if (configActual) {
      configActual.configuracion.defaultViewId = viewId;
    }
  }

  /**
   * Obtiene el ID de la vista por defecto
   */
  getVistaPorDefecto(): string | undefined {
    return this.configuracionEditando()?.configuracion.defaultViewId;
  }

  /**
   * Genera un ID único para una vista final basado en su nombre
   */
  generarViewId(viewName: string | null): string {
    return viewName?.toLowerCase()
      .replace(/[^a-z0-9]/g, '_')
      .replace(/_+/g, '_')
      .replace(/^_|_$/g, '') || 'vista_' + Date.now();
  }

  /**
   * Selecciona una vista como por defecto usando el nombre
   */
  seleccionarVistaPorDefecto(viewName: string): void {
    const viewId = this.generarViewId(viewName);
    this.setVistaPorDefecto(viewId);
  }


  /**
   * Obtiene los filtros formateados para visualización
   * Parsea filtros complejos y los retorna en formato estructurado
   */
  getFiltrosFormateados(config: TablaConfigurada): Array<{ columna: string, filtros: string[], esMultiple: boolean }> {
    const filtros = config.configuracion.filtros || {};
    const resultado: Array<{ columna: string, filtros: string[], esMultiple: boolean }> = [];

    Object.entries(filtros).forEach(([columna, valorFiltro]) => {
      if (valorFiltro && valorFiltro.trim()) {
        const filtrosParseados = this.parseFilterValue(valorFiltro);
        resultado.push({
          columna,
          filtros: filtrosParseados,
          esMultiple: filtrosParseados.length > 1
        });
      }
    });

    return resultado;
  }

  /**
   * Parsea un valor de filtro que puede contener múltiples condiciones
   * Soporta operadores | (OR) y & (AND)
   */
  parseFilterValue(filterValue: string): string[] {
    if (!filterValue || !filterValue.trim()) {
      return [];
    }

    const trimmed = filterValue.trim();

    // Si no hay operadores lógicos, retornar como condición simple
    if (!trimmed.includes('|') && !trimmed.includes('&')) {
      return [trimmed];
    }

    // Separar por | (OR) - división principal
    const orGroups = trimmed.split('|').map(group => group.trim()).filter(group => group);

    // Para cada grupo OR, separar por & (AND) si existe
    const condiciones: string[] = [];
    orGroups.forEach(orGroup => {
      if (orGroup.includes('&')) {
        const andConditions = orGroup.split('&').map(cond => cond.trim()).filter(cond => cond);
        condiciones.push(...andConditions);
      } else {
        condiciones.push(orGroup);
      }
    });

    return condiciones;
  }

  /**
   * Maneja cambios en las configuraciones de tablas cruzadas
   */
  onCrossTabConfigsChange(newConfigs: any[]): void {
    const configActual = this.configuracionEditando();
    if (configActual) {
      configActual.configuracion.crossTabConfigs = newConfigs;
    }
  }

  /**
   * Maneja cambios en las vistas finales
   */
  onFinalViewsChange(newViews: any[]): void {
    const configActual = this.configuracionEditando();
    if (configActual) {
      configActual.configuracion.finalViews = newViews;
    }
  }

  /**
   * Maneja cambios en los filtros
   */
  onFiltradoMapChange(newFiltros: Record<string, string>): void {
    const configActual = this.configuracionEditando();
    if (configActual) {
      configActual.configuracion.filtros = newFiltros;
    }
  }

  
  /**
   * Clona una configuración existente
   * Crea una copia profunda y la prepara para edición
   */
  clonarConfiguracion(config: TablaConfigurada): void {
    // Crear copia profunda de la configuración
    const configClonada: TablaConfigurada = JSON.parse(JSON.stringify(config));

    // Modificar propiedades para identificarla como clonación
    // El ID es de solo lectura, así que lo eliminamos para que el backend asigne uno nuevo
    delete (configClonada as any).id; // Eliminar ID para que se cree como nueva
    configClonada.nombre = `${config.nombre} (copia)`;
    configClonada.created_at = new Date().toISOString();

    // Iniciar modo edición con la configuración clonada
    this.configuracionTemporal = configClonada;
    this.configuracionEditando.set(this.configuracionTemporal);
    this.modoEdicion.set(true);
  }

  /**
   * Verifica si una vista final está seleccionada como por defecto (usado en modo edición)
   */
  esVistaSeleccionada(config: TablaConfigurada, viewName: string): boolean {
    const viewId = this.generarViewId(viewName);
    return viewId === config.configuracion.defaultViewId;
  }

  /**
   * Abrevia nombres largos de vistas manteniendo la legibilidad
   */
  abreviarNombreVista(nombre: string|null): string {
    if(!nombre) return 'S/N';
    if (nombre.length <= 12) return nombre;

    const palabras = nombre.split(' ');
    if (palabras.length > 1) {
      // Para nombres con múltiples palabras, usar iniciales
      return palabras.map(p => p.charAt(0)).join('').toUpperCase();
    } else {
      // Para nombres largos de una palabra, truncar
      return nombre.substring(0, 10) + '...';
    }
  }

  // Métodos para manejar la importación desde JSON

  /**
   * Muestra u oculta el formulario de importación
   */
  toggleImportacion(): void {
    this.mostrarImportacion.set(!this.mostrarImportacion());
    if (!this.mostrarImportacion()) {
      this.limpiarImportacion();
    } else {
      // Cargar JSON de ejemplo como placeholder
      this.jsonImportacion.set(generarJSONEjemplo());
    }
  }

  /**
   * Limpia el formulario de importación
   */
  limpiarImportacion(): void {
    this.jsonImportacion.set('');
    this.erroresImportacion.set([]);
    this.procesandoImportacion.set(false);
  }

  /**
   * Valida y crea una configuración desde el JSON importado
   */
  async validarYCrearDesdeJSON(): Promise<void> {
    this.procesandoImportacion.set(true);
    this.erroresImportacion.set([]);

    try {
      const jsonText = this.jsonImportacion().trim();

      if (!jsonText) {
        this.erroresImportacion.set(['Por favor, pegue un JSON válido en el área de texto']);
        this.procesandoImportacion.set(false);
        return;
      }

      // Validar el JSON
      const resultado = parseAndValidateTablaConfigurada(jsonText);

      if (!resultado.isValid) {
        this.erroresImportacion.set(resultado.errors);
        this.procesandoImportacion.set(false);
        return;
      }

      // Normalizar la configuración
      const configNormalizada = normalizarTablaConfigurada(resultado.data!, this.seccion);

      // Guardar la configuración
      this.saveTablaConfiguracion.emit(configNormalizada);

      // Limpiar formulario y mostrar mensaje de éxito
      this.limpiarImportacion();
      this.mostrarImportacion.set(false);

      // Mostrar mensaje de éxito
      this.dialogService.show({
        title: 'Importación Exitosa',
        body: `La configuración "${configNormalizada.nombre}" ha sido importada correctamente.`,
        tipo: 'info',
        respYes: 'Aceptar',
        size: 'm'
      });

    } catch (error) {
      console.error('Error al importar configuración:', error);
      this.erroresImportacion.set(['Error inesperado: ' + (error as Error).message]);
    } finally {
      this.procesandoImportacion.set(false);
    }
  }

  /**
   * Obtiene un ejemplo de JSON para mostrar al usuario
   */
  getJSONEjemplo(): string {
    return generarJSONEjemplo();
  }

  /**
   * Verifica si hay errores de importación
   */
  hayErroresImportacion(): boolean {
    return this.erroresImportacion().length > 0;
  }
}