import { Component } from '@angular/core';
import { UtilsService } from '../../services/utils.service';
import { ExcelReaderService } from '../../services/excel-reader.service';
import { NgStyle, PercentPipe } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { firstValueFrom } from 'rxjs';
import { ApiServiceService } from '../../services/api/api-service.service';
import { CreditoService } from '../../controllers/credito.service';
import { UtilsEstadoCuentaService } from '../../main/estado-cuenta/services/utils-estado-cuenta.service';
import { EstadoCuentaService } from '../../controllers/estado.cuenta.service';
import { Credito } from '../../models/credito.model';
import { Paginator } from '../../controllers/super.service';
import { RouterLink } from '@angular/router';

@Component({
  selector: 'app-migrar-exceles',
  imports: [
    FormsModule,
    PercentPipe,
    NgStyle,
    RouterLink
  ],
  templateUrl: './migrar-exceles.component.html',
  styleUrl: './migrar-exceles.component.css'
})
export class MigrarExcelesComponent {
  file?: File | null
  sheetNames: string[] = []
  sheetSelected?: string
  chunkSize: number = 0;
  apiUrl: string = 'api/migracion';
  extraData: string = '';
  sendOption: 'ENVIAR SOLO PRIMER CHUNK' | 'ENVIAR TODOS' | 'ESPECIFICA' = 'ENVIAR SOLO PRIMER CHUNK'
  chunkInicial: number = 0
  chunkFinal: number = 1
  actualChunk: number = 0
  loading: boolean = false

  dataSource: any[] = []

  constructor(
    private utils: UtilsService,
    private excelController: ExcelReaderService,
    private api: ApiServiceService,
    private creditoController: CreditoService,
    private estadoCuentaController: EstadoCuentaService,
    private utilsEstadoCuenta: UtilsEstadoCuentaService,
  ) { }

  async onInputChange(event: Event) {
    this.file = this.utils.fileFromInputEvent(event)
    if (this.file) {
      this.sheetNames = await this.excelController.sheetNames(this.file)
      this.sheetSelected = undefined
      console.log(this.sheetNames)
    }
  }

  public async onSheetSelected() {
    if (!this.sheetSelected || !this.file) return
    if (this.sheetSelected == 'estados cuenta') this.apiUrl = 'api/estados_cuentas'
    if (this.sheetNames.includes(this.sheetSelected)) {
      this.dataSource = await this.excelController.readExcelAsJsonList(this.file, this.sheetSelected)
      console.log(this.dataSource)
    }
  }

  private async actualizarEstadosDeCuenta() {
    this.apiUrl = 'api/estados_cuentas'
    this.loading = true
    let extra: any = {
      tipo: this.sheetSelected?.toLowerCase()
    }
    try {
      extra = {
        ...extra,
        ...JSON.parse(this.extraData) ?? {}
      }
    } catch (e) {
      //console.error('DATOS EXTRA INCORRECTOS: ', e)
    }
    if (this.sendOption === 'ENVIAR SOLO PRIMER CHUNK') {
      this.actualChunk = 0
      extra.inicio = 1
      extra.fin = this.chunkSize
      const res = await this.estadosCuenta({
        page: 1,
        per_page: this.chunkSize,
      })
      if (!res) {
        console.error('ESTO TRONO EN EL CHUNK: ', this.actualChunk)
        return
      }
      this.actualChunk = 1
    } else if (this.sendOption === 'ENVIAR TODOS') {
      this.actualChunk = 0
      for (let i = 0; i <= 10000; i += this.chunkSize) {
        extra.inicio = i + 1
        extra.fin = i + this.chunkSize
        const res = await this.estadosCuenta({
          page: this.actualChunk + 1,
          per_page: this.chunkSize,
        })
        if (!res) {
          console.error('ESTO TRONO EN EL CHUNK: ', this.actualChunk)
          return
        }
        this.actualChunk++
        console.info('CHUNK:', this.actualChunk)
      }
      this.loading = false
    } else {
      if (this.chunkFinal < 0 || this.chunkFinal < this.chunkInicial || this.chunkInicial < 0) {
        this.loading = false
        return
      }
      const lastIndex: number = (this.chunkFinal > 0 && this.chunkFinal <= Math.ceil(10000 / this.chunkSize))
        ? (this.chunkFinal * this.chunkSize) : 10000
      this.actualChunk = this.chunkInicial - 1

      for (let i = this.chunkInicial - 1; i < lastIndex; i += this.chunkSize) {
        extra.inicio = i + 1
        extra.fin = i + this.chunkSize
        const res = await this.estadosCuenta({
          page: this.actualChunk,
          per_page: this.chunkSize,
        })
        if (!res) {
          console.error('ESTO TRONO EN EL CHUNK: ', this.actualChunk)
          return
        }
        this.actualChunk++
        console.info('CHUNK:', this.actualChunk)
      }
    }
    this.loading = false
  }

  private async estadosCuenta(paginador: Paginator) {
    const creditos: Credito[] = (await this.creditoController.get([
      {
        key: 'estado',
        operator: '<>',
        value: 'CANCELADO',
      },
      {
        key: 'liberado_fecha',
        operator: 'IS NOT NULL',
        value: null,
      },
      {
        key: 'deleted_at',
        operator: 'IS NULL',
        value: null,
      }
    ], paginador, [
      'abonos',
      'creditosPagos',
      'productosFinancieros.plazos',
      'inversionesProgramas',
      'estadoCuenta',
      "creditoComprobaciones",
      "comprobacionTotalS2c.creditoComprobaciones",
      'convenios.conveniosPagos',
      'juridicos',
      'creditosDespachos.despachos'
    ], {}, false)).data ?? []

    if (!creditos) return;

    creditos.forEach(credito => {
      credito.estado_cuenta = this.utilsEstadoCuenta.calculateEstadoDeCuenta(credito)
    })
    const estadosCuentaNuevos = creditos.filter(credito => credito.estado_cuenta && !credito.estado_cuenta.id).map(credito => credito.estado_cuenta!)
    const estadosCuentaActualizar = creditos.filter(credito => credito.estado_cuenta && !!credito.estado_cuenta.id).map(credito => credito.estado_cuenta!)
    let res = true
    if (estadosCuentaNuevos.length > 0) {
      res = res && await this.estadoCuentaController.multipleNews(estadosCuentaNuevos)
    }
    if (estadosCuentaActualizar.length > 0) {
      res = res && await this.estadoCuentaController.multipleUpdate(estadosCuentaActualizar)
    }
    if (!res) {
      console.error([...estadosCuentaActualizar, ...estadosCuentaNuevos])
    }
    if (estadosCuentaActualizar.length == 0 && estadosCuentaNuevos.length == 0) return false;
    return res;
  }

  async subir() {
    if (!this.apiUrl) return
    if (!this.file || this.sheetSelected == 'estados cuenta') {
      this.actualizarEstadosDeCuenta()
      return
    }
    this.loading = true
    let extra: any = {
      tipo: this.sheetSelected?.toLowerCase()
    }
    try {
      extra = {
        ...extra,
        ...JSON.parse(this.extraData) ?? {}
      }
    } catch (e) {
      //console.error('DATOS EXTRA INCORRECTOS: ', e)
    }
    console.log(this.extraData)
    console.log(extra)

    if (this.sendOption === 'ENVIAR SOLO PRIMER CHUNK') {
      this.actualChunk = 0
      const data = this.dividedDataSource()[0]
      const res = await firstValueFrom(this.api.post(this.apiUrl, data, extra))
      this.actualChunk = 1
      console.log(res)
    } else if (this.sendOption === 'ENVIAR TODOS') {
      const data = this.dataSource
      this.actualChunk = 0
      this.chunkFinal = Math.ceil(data.length / this.chunkSize)

      const lastIndex: number = (this.chunkFinal > 0 && this.chunkFinal <= Math.ceil(data.length / this.chunkSize))
        ? (this.chunkFinal * this.chunkSize) : data.length
      this.actualChunk = this.chunkInicial - 1

      for (let i = 0; i <= data.length; i += this.chunkSize) {
        extra.inicio = this.chunkInicial - 1
        extra.fin = lastIndex - 1

        const res = await firstValueFrom(this.api.post(this.apiUrl, data.slice(i, i + this.chunkSize), extra))
        if (!res.status) {
          console.error('Esto trono en el chunk: ', this.actualChunk)
          this.loading = false
          return
        }
        console.log(res)
        this.actualChunk++
      }
      this.loading = false
    } else {
      const data = this.dataSource
      if (data.length == 0) {
        console.error('dataSource is empty')
        this.loading = false
        return
      }
      if (this.chunkFinal < 0 || this.chunkFinal < this.chunkInicial || this.chunkInicial < 0) {
        this.loading = false
        return
      }
      const lastIndex: number = (this.chunkFinal > 0 && this.chunkFinal <= Math.ceil(data.length / this.chunkSize))
        ? (this.chunkFinal * this.chunkSize) : data.length
      this.actualChunk = this.chunkInicial - 1

      console.log('id Inicial: ', this.chunkInicial * this.chunkSize, ' LastIndex:', lastIndex)
      for (let i = (this.chunkInicial * this.chunkSize) - 1; i <= lastIndex; i += this.chunkSize) {
        extra.inicio = this.chunkInicial - 1
        extra.fin = lastIndex - 1

        const res = await firstValueFrom(this.api.post(this.apiUrl, data.slice(i, i + this.chunkSize), extra))
        if (!res.status) {
          console.error('Esto trono en el chunk: ', this.actualChunk)
          this.loading = false
          return
        }
        console.info('chunk:', i / this.chunkSize);
        console.log(res)
      }
    }
    this.loading = false
  }

  dividedDataSource(chunkSize: number = this.chunkSize): any[][] {
    if (!this.dataSource || this.dataSource.length === 0) {
      return [];
    }

    const result: any[][] = [];
    for (let i = 0; i < this.dataSource.length; i += chunkSize) {
      result.push(this.dataSource.slice(i, i + chunkSize));
    }

    return result;
  }

}
