
import { Component } from '@angular/core';
import { Form, GenericFormComponent } from '../../../shared/generic-form/generic-form.component';
import { FormField } from '../../../shared/generic-form/form-field/form-field.component';

const FORM_DATA:Form=[
  {
    key:"regimen",
    label:"Regimen",
    options:["PERSONA FISICA CON ACTIVIDAD EMPRESARIAL", "PERSONA MORAL"]
  },
  {
    key:"nombre",
    label:"Nombre",
    type:"text"
  },
  {
    key:"programa",
    label:"Programa",
    type:"text"
  },
  {
    key:"anio_programa",
    label:"Año del Programa",
    type:"date"
  },
  {
    key:"aplica",
    label:"¿Quién puede aplicar?",
    options:["NUEVOS", "RENOVACION", "REESTRUCTURA"]
  },
  {
    key:"abreviatura",
    label:"Abreviatura",
    type:"text"
  },
]

@Component({
    selector: 'app-form-productos-comerciales',
    imports: [
    GenericFormComponent
],
    templateUrl: './form-productos-comerciales.component.html',
    styleUrl: './form-productos-comerciales.component.css'
})
export class FormProductosComercialesComponent {
  form:Form=FORM_DATA

  onFormChanges(){
    this.setAbreviatura()
  }

  setAbreviatura(){
    console.log(this.form)
    const abreviatura=this.form.find((field)=> (field as FormField).key=='abreviatura' ) as FormField
    if(abreviatura){
      const nombre = this.form.find((field)=> (field as FormField).key=='nombre' ) as FormField
      if(nombre && nombre.value){ 
        abreviatura.value= nombre.value.toString().split(' ').map((item)=> item.substring(0,3)).join('')
        console.log(abreviatura)
      }
    }
  }
}
