import { Component } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ApiServiceService } from '../../services/api/api-service.service';
import { firstValueFrom } from 'rxjs';

@Component({
    selector: 'app-utileria',
    imports: [
        FormsModule,
    ],
    templateUrl: './utileria.component.html',
    styleUrl: './utileria.component.css'
})
export class UtileriaComponent {

  creditoId:number=0

  constructor(private api:ApiServiceService){}

  public async refrescarReferenciaBancaria(){
    const res= await firstValueFrom(this.api.post<string>('api/utils/referencia_bancaria/'+this.creditoId))
    console.log(res)
  }

}
