import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Component } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { firstValueFrom } from 'rxjs';
import { ApiServiceService } from '../../services/api/api-service.service';

@Component({
    selector: 'app-migrar-gestiones',
    imports: [
        FormsModule,
    ],
    templateUrl: './migrar-gestiones.component.html',
    styleUrl: './migrar-gestiones.component.css'
})
export class MigrarGestionesComponent {
  phptoken:string=''
  creditoInicio:number=1
  creditoFin=9700
  creditoId:number=1
  chunkSize=50

  constructor(
    private api:ApiServiceService,
  ){}

  ngOnInit(){
  }

  public async migrarCredito(){
    for(let i =this.creditoInicio; i<=this.creditoFin; i+=this.chunkSize){
      let fin = i+this.chunkSize;
      fin = fin > this.creditoFin ? this.creditoFin: fin;
      const res =await this.postData(i, fin)
      if(res){
        console.error('ESTO TRONO EN EL CREDITO ',i);
        return;
      }
    }
  }

  private async postData(inicio:number, fin:number){
    const res= await firstValueFrom(
      this.api.post('api/migracion/gestiones', {
        phpcookie: 'PHPSESSID='+this.phptoken,
        credito_inicio:inicio,
        credito_fin:fin,
      })
    )
    console.log(res)
    return res.status
  }
}
