import { TablaConfigurada, TablaConfig, VisualizationMode } from '../main/informes/informe-tabla-configurada/interfaces/tabla.configurada';

/**
 * Interfaz para resultado de validación
 */
export interface ValidationResult<T> {
  isValid: boolean;
  data?: T;
  errors: string[];
}

/**
 * Type Guard para validar que un objeto es VisualizationMode válido
 */
export function isValidVisualizationMode(value: any): value is VisualizationMode {
  return value === 'tables' || value === 'graphs';
}

/**
 * Type Guard para validar que un objeto es una TablaConfig válida
 */
export function isValidTablaConfig(obj: any): obj is TablaConfig {
  if (!obj || typeof obj !== 'object') {
    return false;
  }

  // Validar que finalViews sea un array (puede estar vacío)
  if (!Array.isArray(obj.finalViews)) {
    return false;
  }

  // Validar que crossTabConfigs sea un array (puede estar vacío)
  if (!Array.isArray(obj.crossTabConfigs)) {
    return false;
  }

  // Validar que filtros sea un objeto (puede estar vacío)
  if (!obj.filtros || typeof obj.filtros !== 'object') {
    return false;
  }

  // Validar defaultViewId si existe
  if (obj.defaultViewId !== undefined && obj.defaultViewId !== null) {
    if (typeof obj.defaultViewId !== 'string') {
      return false;
    }
  }

  // Validar visualizationMode si existe
  if (obj.visualizationMode !== undefined && obj.visualizationMode !== null) {
    if (!isValidVisualizationMode(obj.visualizationMode)) {
      return false;
    }
  }

  return true;
}

/**
 * Type Guard para validar que un objeto es una TablaConfigurada parcial válida
 * (sin requerir id, created_at, updated_at)
 */
export function isValidPartialTablaConfigurada(obj: any): obj is Partial<TablaConfigurada> {
  if (!obj || typeof obj !== 'object') {
    return false;
  }

  // Validar nombre si existe
  if (obj.nombre !== undefined && typeof obj.nombre !== 'string') {
    return false;
  }

  // Validar seccion si existe
  if (obj.seccion !== undefined && typeof obj.seccion !== 'string') {
    return false;
  }

  // Validar que configuración exista y sea válida
  if (!obj.configuracion || !isValidTablaConfig(obj.configuracion)) {
    return false;
  }

  return true;
}

/**
 * Parsea y valida un string JSON como TablaConfigurada parcial
 */
export function parseAndValidateTablaConfigurada(jsonString: string): ValidationResult<Partial<TablaConfigurada>> {
  const errors: string[] = [];

  try {
    // 1. Validar que sea JSON válido
    const parsed = JSON.parse(jsonString);

    // 2. Validar que sea un objeto
    if (!parsed || typeof parsed !== 'object') {
      errors.push('El JSON debe ser un objeto válido');
      return { isValid: false, errors };
    }

    // 3. Validar estructura de TablaConfigurada parcial
    if (!isValidPartialTablaConfigurada(parsed)) {
      errors.push('El JSON no tiene la estructura válida de TablaConfigurada');

      // Validaciones específicas para dar feedback detallado
      if (parsed.configuracion === undefined) {
        errors.push('Falta el campo requerido: configuracion');
      } else if (!isValidTablaConfig(parsed.configuracion)) {
        errors.push('El campo configuracion no tiene la estructura válida');

        if (!Array.isArray(parsed.configuracion.finalViews)) {
          errors.push('configuracion.finalViews debe ser un array');
        }

        if (!Array.isArray(parsed.configuracion.crossTabConfigs)) {
          errors.push('configuracion.crossTabConfigs debe ser un array');
        }

        if (!parsed.configuracion.filtros || typeof parsed.configuracion.filtros !== 'object') {
          errors.push('configuracion.filtros debe ser un objeto');
        }
      }

      if (parsed.nombre !== undefined && typeof parsed.nombre !== 'string') {
        errors.push('El campo nombre debe ser un string');
      }

      if (parsed.seccion !== undefined && typeof parsed.seccion !== 'string') {
        errors.push('El campo seccion debe ser un string');
      }

      return { isValid: false, errors };
    }

    return { isValid: true, data: parsed, errors };
  } catch (error) {
    if (error instanceof SyntaxError) {
      errors.push('JSON inválido: ' + error.message);
    } else {
      errors.push('Error al procesar el JSON: ' + (error as Error).message);
    }

    return { isValid: false, errors };
  }
}

/**
 * Normaliza una TablaConfigurada parcial para crear una nueva completa
 */
export function normalizarTablaConfigurada(
  parcial: Partial<TablaConfigurada>,
  seccionActual: string
): TablaConfigurada {
  const ahora = new Date().toISOString();

  return {
    // Campos del servidor (se generan automáticamente)
    id: 0,
    created_at: ahora,
    updated_at: ahora,

    // Campos del usuario (con valores por defecto si faltan)
    nombre: parcial.nombre || `Configuración importada ${new Date().toLocaleDateString()}`,
    seccion: seccionActual,

    // Configuración (con valores por defecto si faltan)
    configuracion: {
      ...parcial.configuracion!,
      defaultViewId: parcial.configuracion?.defaultViewId || undefined,
      visualizationMode: parcial.configuracion?.visualizationMode || 'tables'
    }
  };
}

/**
 * Genera un JSON de ejemplo para que el usuario vea el formato esperado
 */
export function generarJSONEjemplo(): string {
  const ejemplo = {
    nombre: "Ejemplo de configuración",
    configuracion: {
      finalViews: [
        {
          name: "Vista de ejemplo",
          type: "table",
          columns: ["columna1", "columna2"]
        }
      ],
      crossTabConfigs: [],
      filtros: {
        "columna1": "valor_ejemplo"
      },
      defaultViewId: null,
      visualizationMode: "tables"
    }
  };

  return JSON.stringify(ejemplo, null, 2);
}