import { Component, inject, signal } from '@angular/core';
import { DASHBOARD_HISTORICO_SECCIONES, Tab } from '../../main/informes/dashboard-historico/dashboard-historico.component';
import { PorProgramasSectionComponent } from "../../main/informes/dashboard-historico/components/por-programas-section/por-programas-section.component";
import { TablaConfigurada } from '../../main/informes/informe-tabla-configurada/interfaces/tabla.configurada';
import { TablaConfiguradaService } from '../../main/informes/informe-tabla-configurada/services/tabla.configurada.service';
import { InformeTablaDinamicaLocalComponent } from "../../main/informes/informe-tabla-dinamica-local/informe-tabla-dinamica-local.component";
import { ConsolidadoHistoricoCombinadoService } from '../../main/reportes/services/consolidado-historico-combinado.service';
import { ConfiguracionTablasSeccionComponent } from "./components/configuracion-tablas-seccion/configuracion-tablas-seccion.component";

@Component({
  selector: 'app-configuracion-historico',
  imports: [ConfiguracionTablasSeccionComponent],
  templateUrl: './configuracion-historico.component.html',
  styleUrl: './configuracion-historico.component.css'
})
export class ConfiguracionHistoricoComponent {
  activeTab = signal('programas');

  tabs: Tab[] = DASHBOARD_HISTORICO_SECCIONES;

  tablasConfiguradas: TablaConfigurada[] = []

  rawData: any[] = []

  //services
  private tablaConfiguradaController = inject(TablaConfiguradaService)
  private consolidadoService = inject(ConsolidadoHistoricoCombinadoService);

  ngOnInit(): void {
    this.setTablasConfiguradas()
    this.setConsolidadoData()
  }

  public selectTab(tabId: string): void {
    this.activeTab.set(tabId);
  }

  public tablasConfiguradasFromSeccion(seccion: string) {
    return this.tablasConfiguradas.filter(r => r.seccion === seccion)
  }

  public addTablaConfiguracion(seccion: string) {
    this.tablasConfiguradas.push({
      seccion: seccion,
      configuracion: {
        finalViews: [],
        filterBasedConfigs: [],
        crossTabConfigs: [],
        filtros: {},
        defaultViewId: undefined,
      },
      nombre: '',
      id: 0,
      created_at: ''
    })

    console.log(this.tablasConfiguradas)
  }

  public async saveTablaConfiguracion(config: TablaConfigurada) {
    await this.tablaConfiguradaController.createOrUpdate(config, false)
    this.setTablasConfiguradas()
    console.log(config)
  }

  public async handleAddTablaConfiguracion(seccion: string) {
    this.addTablaConfiguracion(seccion)
  }

  public async handleDeleteTablaConfiguracion(config: TablaConfigurada) {
    await this.tablaConfiguradaController.switch(config)
    this.setTablasConfiguradas()
  }

  private async setTablasConfiguradas() {
    const data = await this.tablaConfiguradaController.all({
      conditionals: {
        deleted_at: null
      },
      loader: false
    })
    this.tablasConfiguradas = data.map(item => ({
      ...item,
      configuracion: JSON.parse(item.configuracion as string)
    }))
  }

  private async setConsolidadoData() {
    this.rawData = await this.consolidadoService.fetchDataMaped()
  }

}
