import { Component, SimpleChanges, ViewChild, viewChild } from '@angular/core';
import { TablaComponent, TableDefinition } from "../../../shared/tabla/tabla.component";
import { DocumentoService } from '../../../controllers/documento.service';
import { Router } from '@angular/router';
import { FormularioFlotanteComponent } from '../../../shared/formulario-flotante/formulario-flotante.component';
import { FormDocumentoComponent } from "../form-documento/form-documento.component";
import { Documento } from '../../../models/documento.model';

const TABLA_DEF:TableDefinition={
  columns:[
    {
      key:'nombre',
      header:'Nombre',
    },
    {
      key:'usuarios',
      subKey:'nombre',
      header:'Creador',
    },
    {
      key:'created_at',
      header:'Creado en',
      pipe:'date'
    }
  ]
}

@Component({
    selector: 'app-tabla-documento',
    imports: [
        TablaComponent,
        FormularioFlotanteComponent,
        FormDocumentoComponent
    ],
    templateUrl: './tabla-documento.component.html',
    styleUrl: './tabla-documento.component.css'
})
export class TablaDocumentoComponent {
  tabla= TABLA_DEF
  showAdd:boolean=false
  edit?:Documento
  @ViewChild('tablaRef') tablaRef!: TablaComponent<Documento>

  constructor(
    public documentoController:DocumentoService,
    private router: Router
  ){}

  ngOnChanges(changes:SimpleChanges){
    console.log(this.showAdd)
    if(changes['showAdd'] && !this.showAdd){
      console.log("se cerro form")
      this.tablaRef.getData()
    }
  }

  updateTabla(){
    if(!this.showAdd){
      this.tablaRef.getData()
    }
  }

  nuevo(){
    this.edit=undefined
    this.showAdd=true
  }

  editar(row:Documento){
    this.edit=row
    this.showAdd=true
  }
}